let sid=0;
function table(headers,rows){return '<div class="scroll"><table><thead><tr>'+headers.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>'}
function plot(rows,key,color='#ffb157',bars=false){if(!rows.length)return '<p class="sub">No sessions in this range.</p>';let id='chart'+(++sid),W=780,H=210,L=61,R=22,T=12,B=25,vs=rows.map(r=>r[key]),lo=Math.min(...vs,0),hi=Math.max(...vs,0),range=hi-lo||1,x=i=>L+(W-L-R)*(i+.5)/rows.length,y=v=>T+(hi-v)/range*(H-T-B),points=vs.map((v,i)=>x(i)+','+y(v)).join(' '),grid='',marks='';for(let j=0;j<5;j++){let v=hi-range*j/4;grid+='<path stroke="#30363e" stroke-dasharray="3 5" d="M'+L+' '+y(v)+'H'+(W-R)+'"/><text x="2" y="'+(y(v)+4)+'">'+fmt(v,Math.abs(v)>100?0:1)+'</text>'}for(let i of new Set([0,Math.floor(rows.length/3),Math.floor(rows.length*2/3),rows.length-1]))grid+='<text x="'+x(i)+'" y="206" text-anchor="middle">'+rows[i].d.slice(5)+'</text>';if(bars)marks=vs.map((v,i)=>'<rect x="'+(x(i)-Math.min(10,240/rows.length))+'" y="'+Math.min(y(0),y(v))+'" width="'+Math.min(20,480/rows.length)+'" height="'+Math.max(1,Math.abs(y(v)-y(0)))+'" fill="'+(v>=0?'#48d3a0':'#ff797e')+'"/>').join('');else marks='<polygon points="'+x(0)+','+(H-B)+' '+points+' '+x(vs.length-1)+','+(H-B)+'" fill="url(#'+id+')"/><polyline pathLength="1" fill="none" stroke="'+color+'" stroke-width="3" stroke-linejoin="round" points="'+points+'"/>';let html='<div class="plot" id="p'+id+'"><svg class="chart" viewBox="0 0 780 210" preserveAspectRatio="none" fill="#a4abb5" font-family="monospace" font-size="12"><defs><linearGradient id="'+id+'" x2="0" y2="1"><stop stop-color="'+color+'" stop-opacity=".29"/><stop offset="1" stop-color="'+color+'" stop-opacity=".01"/></linearGradient></defs>'+grid+marks+'<path class="cross" stroke="#afb5bc" stroke-dasharray="4 4"/></svg><div class="tip"></div></div>';queueMicrotask(()=>{let el=$('p'+id);if(!el)return;el.onpointermove=e=>{let b=el.getBoundingClientRect(),f=(e.clientX-b.left)/b.width,i=Math.max(0,Math.min(rows.length-1,Math.floor((f*W-L)/(W-L-R)*rows.length))),tip=el.lastElementChild;el.querySelector('.cross').setAttribute('d','M'+x(i)+' 8V185');tip.textContent=rows[i].tip||rows[i].d+'  '+signed(vs[i])+'%';Object.assign(tip.style,{display:'block',left:Math.max(0,Math.min(b.width-180,f*b.width+10))+'px',top:'5px'})};el.onpointerleave=()=>{el.lastElementChild.style.display='none';el.querySelector('.cross').removeAttribute('d')}});return html}
function spark(r){let vs=r.map(x=>x.c),lo=Math.min(...vs),hi=Math.max(...vs);return '<svg viewBox="0 0 100 40" preserveAspectRatio="none"><polyline pathLength="1" fill="none" stroke="'+(r.at(-1)?.a<0?'#ff797e':'#48d3a0')+'" stroke-width="2" points="'+vs.map((v,i)=>(i*100/(vs.length-1||1))+','+(37-34*(v-lo)/(hi-lo||1))).join(' ')+'"/></svg>'}
